<script lang="ts">
  import JobPreviewScene from './JobPreviewScene.svelte';
  import type { JobPreflightResult } from './jobPreflight';
  import type { ImportSummary, StockDefinition, StockMode, PartPlacement, PartOrientation, WorkCoordinateSystem } from './types';
  export let result:JobPreflightResult;
  export let summary:ImportSummary;
  export let stock:StockDefinition;
  export let stockMode:StockMode;
  export let placement:PartPlacement;
  export let orientation:PartOrientation;
  export let wcs:WorkCoordinateSystem;
  let showJobPreview=false;
</script>
<p class="eyebrow">05 · Prüfen</p><h2>Gesamtjob</h2>
<div class="overall" class:pass={result.level==='pass'} class:warn={result.level==='warn'} class:fail={result.level==='fail'}><strong>{result.level.toUpperCase()}</strong><span>{result.level==='pass'?'Alle Bearbeitungen besitzen eine freigegebene kanonische Werkzeugbahn.':result.level==='warn'?'Der Gesamtjob ist freigabefähig, enthält aber Hinweise.':'Mindestens eine Bearbeitung oder ihre kanonische Werkzeugbahn ist nicht freigegeben. Der Gesamtjob darf nicht ausgegeben werden.'}</span></div>
<button class="preview-button" onclick={()=>showJobPreview=true}>Gesamtjob anzeigen</button>
<p class="preview-note">005A zeigt Rohling/Bauteil als reine Renderreferenz und ausschließlich die bereits im Job-Preflight materialisierten Maschinenbewegungen. Keine CAM-Neuberechnung, keine Ersatzbahn.</p>
<div class="facts"><span>{result.enabledCount} Bearbeitungen</span><span>{result.toolChanges} Werkzeugwechsel</span><span>Operation → kanonischer Toolpath → Prüfen → Postprozessor</span></div>
<div class="operations">{#each result.operations as op}<div class="op"><span class="status" class:pass={op.level==='pass'} class:warn={op.level==='warn'} class:fail={op.level==='fail'}>{op.level.toUpperCase()}</span><div><strong>{String(op.index).padStart(2,'0')} · {op.label}</strong><p>{op.detail}</p><p class="canonical">Kanonisch · {op.canonical}</p>{#if op.toolAssembly}<div class="assembly" class:pass={op.toolAssembly.level==='pass'} class:warn={op.toolAssembly.level==='warn'} class:fail={op.toolAssembly.level==='fail'}><strong>004Q Werkzeugbaugruppe · {op.toolAssembly.level.toUpperCase()}</strong><span>Schneidenlänge {op.toolAssembly.cuttingLengthMm.toFixed(1)} mm · Auskragung {op.toolAssembly.stickoutMm.toFixed(1)} mm · Schaft Ø {op.toolAssembly.shaftDiameterMm.toFixed(1)} mm · Halter Ø {op.toolAssembly.holderDiameterMm.toFixed(1)} mm</span><span>{op.toolAssembly.level==='pass'?'Reichweite und Halterfreiraum im 2.5D-Reststockmodell freigegeben.':op.toolAssembly.level==='warn'?'Reichweite ist freigegeben, aber die Schneidenlänge erzeugt einen Hinweis.':'Werkzeugreichweite oder Halterfreiraum ist nicht freigegeben.'}</span></div>{/if}{#if op.fixtureCollision}<div class="fixture-check" class:pass={op.fixtureCollision.level==='pass'} class:fail={op.fixtureCollision.level==='fail'}><strong>004R Spannmittel · {op.fixtureCollision.level.toUpperCase()}</strong><span>{op.fixtureCollision.checkedFixtures} aktiv geprüft · {op.fixtureCollision.hits} Treffer · {op.fixtureCollision.kinds.length?op.fixtureCollision.kinds.map(kind=>kind==='cutter'?'Fräser':kind==='shank'?'Schaft':'Halter').join(' / '):'kein Konflikt'}</span></div>{/if}{#if op.spindleHead}<div class="spindle-check" class:pass={op.spindleHead.level==='pass'} class:warn={op.spindleHead.level==='warn'} class:fail={op.spindleHead.level==='fail'}><strong>004U Spindelkopf · {op.spindleHead.level.toUpperCase()}</strong><span>{op.spindleHead.checkedFixtures} Spannmittel · {op.spindleHead.checkedMotions} Bewegungen · {op.spindleHead.hits} Treffer</span><span>{op.spindleHead.kinds.length?op.spindleHead.kinds.map(kind=>kind==='spindle-nose'?'Spindelnase/Spannzange':'Z-Schlitten').join(' / '):'kein Konflikt'}</span></div>{/if}{#if op.machineEnvelope}<div class="machine-check" class:pass={op.machineEnvelope.level==='pass'} class:warn={op.machineEnvelope.level==='warn'} class:fail={op.machineEnvelope.level==='fail'}><strong>004S Maschinenraum · {op.machineEnvelope.level.toUpperCase()}</strong><span>{op.machineEnvelope.checkedPoints} Punkte geprüft · {op.machineEnvelope.limitHits} Grenzverletzung{op.machineEnvelope.limitHits===1?'':'en'} · {op.machineEnvelope.marginHits} Warnabstand-Treffer</span><span>{op.machineEnvelope.usesExplicitMotions?'Vollständige canonical motions verwendet.':'Fallback: Runs + Entry/Exit; vollständige Rapid-Kette noch nicht verfügbar.'}</span></div>{/if}{#each op.errors as message}<p class="message fail-text">{message}</p>{/each}{#each op.warnings as message}<p class="message warn-text">{message}</p>{/each}</div></div>{/each}</div>
<p class="note"><strong>Prüfregel:</strong> No blind toolpaths. Eine fachlich gültige Bearbeitung ist erst dann freigegeben, wenn auch ihre kanonische Werkzeug- bzw. Maschinenbahn vollständig erzeugt und geprüft werden kann. Ein einziges FAIL setzt den gesamten Job auf FAIL.</p>
{#if showJobPreview}<JobPreviewScene {result} {summary} {stock} {stockMode} {placement} {orientation} {wcs} onClose={()=>showJobPreview=false}/>{/if}
